window.LQ=window.LQ||{};
Object.assign(window.LQ,{
"p38m1":[
 {id:"p38m1q1", q:"In 8-bit two's complement, which bit pattern stores −12?", options:["0xF3","0xF4","0x8C","0x0C"], answer:1, why:"12 is 00001100; invert every bit to get 11110011, then add one: 11110100 = 0xF4. 0xF3 forgets the +1 (that is ones' complement), and 0x8C is sign-magnitude, which only sets the top bit."},
 {id:"p38m1q2", q:"Two 8-bit two's-complement registers hold +100 and +50. The adder adds them and keeps 8 bits. What does the result read as?", options:["+150, because the adder's carry-out keeps the extra bit","+22, because the carry out of bit 7 is discarded","−22, because overflow flips only the sign bit","−106, because two positives produced a negative pattern"], answer:3, why:"100 + 50 = 150 = 1001 0110, which fits in 8 bits with no carry-out; its top bit is set, so it reads as 150 − 256 = −106. Same-sign operands giving an opposite-sign result is overflow, and RISC-V raises no flag for it, so code must check."},
 {id:"p38m1q3", q:"Which IEEE 754 single-precision word encodes −2.5?", options:["0xC0200000","0x40200000","0xC0A00000","0x80A00000"], answer:0, why:"2.5 = 10.1₂ = 1.01 × 2¹, so sign 1, exponent 1 + 127 = 128 = 10000000, fraction 0100…, giving 0xC0200000. 0x40200000 drops the sign, 0xC0A00000 is −5.0 (exponent one too high) and 0x80A00000 forgets the 127 bias."},
 {id:"p38m1q4", q:"A register-to-register path has clock-to-output 60 ps, combinational logic 340 ps and setup time 100 ps. What is the highest safe clock frequency?", options:["About 2.9 GHz, set by the 340 ps of logic alone","About 2.5 GHz, set by logic plus clock-to-output","About 2.0 GHz, set by all three delays together","About 1.0 GHz, since the data needs two clock edges"], answer:2, why:"T ≥ t_cq + t_logic + t_setup = 60 + 340 + 100 = 500 ps, so f ≤ 2.0 GHz. Counting only the 340 ps of logic (2.9 GHz) ignores the flip-flop overheads at both ends, so the second register would capture data that has not settled."},
 {id:"p38m1q5", q:"A single-cycle core has instruction memory 250 ps, register read 150 ps, ALU 200 ps, data memory 300 ps and register write 100 ps. What is the clock period, and how long does an add occupy?", options:["700 ps, since add is the most common instruction","1,000 ps; an add needs 700 ps but uses a full cycle","900 ps, set by the store, the slowest memory user","1,000 ps for loads and 700 ps for adds, each its own time"], answer:1, why:"A load uses all five units: 250 + 150 + 200 + 300 + 100 = 1,000 ps, and one clock must fit the slowest instruction. An add needs only 250 + 150 + 200 + 100 = 700 ps yet still occupies a whole 1,000 ps cycle; a single-cycle design cannot give it a shorter one."}
],
"p38m2":[
 {id:"p38m2q1", q:"A beq must reach a label 6,000 bytes ahead. Based on the RV32I encoding rules, what is true?", options:["It encodes normally, because the 12-bit field can count up to 4,095 bytes","It encodes if the offset is stored in 4-byte instruction units","It fails, because no RISC-V jump can travel more than 4 KiB","Too far for beq's ±4 KiB; a jal, with ±1 MiB reach, must make the jump"], answer:3, why:"B-type immediates are signed 13-bit byte offsets (lowest bit implied 0), giving ±4 KiB, so 6,000 bytes is out of range and the branch must be inverted around a jal, which reaches ±1 MiB. The field is signed and counts 2-byte units, not 4-byte ones."},
 {id:"p38m2q2", q:"You write li t0, 3000 in RV32I assembly. What does the assembler emit?", options:["addi t0, zero, 3000, since 12 bits reach 4,095","lui t0, 3000 followed by addi t0, t0, 0","lui t0, 1 followed by addi t0, t0, -1096","lui t0, 1 followed by addi t0, t0, 1096"], answer:2, why:"addi's 12-bit immediate is signed, −2048 to +2047, so 3000 needs two instructions: lui t0, 1 sets t0 = 4096 and adding −1096 gives 3000. Reading the field as unsigned 0–4,095 is the trap, and lui t0, 3000 would load 3000 × 4096."},
 {id:"p38m2q3", q:"A function starts with addi sp, sp, -16; sw s0, 8(sp), keeps a value in s0, calls jal ra, h, then restores s0, frees the frame and executes ret. It never returns to its caller. Why?", options:["ra was not saved, so jal overwrote it and ret loops back here","s0 is caller-saved, so h was free to destroy it","The 16-byte frame breaks alignment, which the ABI requires to be 8 bytes","ret only works in leaf functions; non-leaf ones must use jalr x0, 0(t0)"], answer:0, why:"jal ra, h writes a new return address into ra, destroying the caller's. ret is jalr x0, 0(ra), so it lands just after the call inside this same function. s0 is callee-saved, so h must preserve it; the fix is sw ra, 12(sp) in the prologue and a matching lw before ret."},
 {id:"p38m2q4", q:"A disassembler shows the 32-bit word 0x40B50533. Which instruction is it?", options:["add a0, a0, a1","sra a0, a0, a1","sub a0, a0, a1","sub a1, a0, a0"], answer:2, why:"Opcode bits 6:0 = 0110011 (R-type); rd = 01010 = a0; funct3 = 000; rs1 = 01010 = a0; rs2 = 01011 = a1; funct7 = 0100000. funct3 000 with funct7 0100000 is sub. add has funct7 0000000 (0x00B50533), and sra uses funct3 101."},
 {id:"p38m2q5", q:"A vendor's core reports the ISA string rv64imac_zicsr. Can it run a Linux distribution built for RV64GC?", options:["Yes, because the C extension is all a Linux distribution requires","No: G also requires F, D and Zifencei, which it lacks","No, because G includes the V vector extension, which it lacks","Yes, because G is shorthand for any general-purpose 64-bit core"], answer:1, why:"G abbreviates IMAFD_Zicsr_Zifencei, so RV64GC code uses hardware single and double floating point and traps as illegal instructions on a core without F and D. V is not part of G; it is the RVA23 profile that makes V mandatory."}
],
"p38m3":[
 {id:"p38m3q1", q:"Seven independent instructions run on a five-stage pipeline with a 250 ps clock and no hazards. How long from the first fetch to the last write-back?", options:["1.75 ns: one instruction finishes per cycle","2.75 ns: 7 + 5 − 1 = 11 cycles","8.75 ns: each takes five cycles in turn","1.25 ns: the latency of a single instruction"], answer:1, why:"Cycles = n + stages − 1 = 7 + 4 = 11, and 11 × 250 ps = 2.75 ns. Each instruction still takes five cycles; they overlap. 8.75 ns ignores the overlap, and 1.75 ns ignores the four cycles needed to fill the pipeline."},
 {id:"p38m3q2", q:"With forwarding in the five-stage pipeline, how many bubbles does this cost?\nlw x5, 0(x10)\naddi x11, x12, 1\nadd x6, x5, x7", options:["One: a load followed by its use always costs a bubble","Two: x5 is not available until the lw writes back","None: the independent addi fills the load-use gap","None: forwarding removes every kind of data hazard"], answer:2, why:"The load's data is ready at the end of MEM in cycle 4; the add, one slot later, reaches EX in cycle 5 and takes x5 from the MEM/WB register with no stall. The addi is the compiler scheduling the lesson describes; forwarding alone would not save an adjacent load-use pair."},
 {id:"p38m3q3", q:"A loop's back-edge branch is taken 9 times, then falls through once, and the loop runs thousands of times. In steady state, how many mispredictions per pass does a 1-bit predictor make, and a 2-bit saturating counter?", options:["1-bit: 2; 2-bit: 1","1-bit: 1; 2-bit: 1","1-bit: 2; 2-bit: 2","1-bit: 1; 2-bit: 0"], answer:0, why:"A 1-bit entry misses the exit, flips to not-taken, then misses the first branch of the next pass: two per pass. A 2-bit counter at strongly taken drops only to weakly taken on the exit, so it still predicts taken next time: one per pass."},
 {id:"p38m3q4", q:"Profiling shows 60% of a program's run time in one function. You make that function 4× faster. What is the overall speedup?", options:["About 2.4×","About 4.0×","About 2.5×","About 1.8×"], answer:3, why:"Amdahl: 1 / ((1 − 0.6) + 0.6/4) = 1 / 0.55 ≈ 1.82×. The untouched 40% dominates. 2.5× is the ceiling even if the function became infinitely fast, and 4× pretends the whole program sped up."},
 {id:"p38m3q5", q:"A secure-element team picks a simple in-order RISC-V core with no branch prediction or speculation. Why does that remove the Spectre-class risk the lesson describes?", options:["The RISC-V specification forbids speculative loads on every compliant implementation","No instruction runs past an unresolved branch, so no secret-steered line gets cached","In-order cores carry no cache at all, so there is no access timing for anyone to measure","Its rollback restores the cache along with registers and memory"], answer:1, why:"Spectre needs transient execution: work on a predicted path that leaves a cache footprint after rollback. A core that never speculates never touches out-of-bounds data on a wrong path. In-order cores can still have caches, and the RISC-V spec leaves leakage to implementations."}
],
"p38m4":[
 {id:"p38m4q1", q:"A 64 KB, 4-way set-associative cache with 32-byte lines sits on a 32-bit address. How do the address bits split?", options:["Offset 5, index 11, tag 16","Offset 6, index 9, tag 17","Offset 5, index 7, tag 20","Offset 5, index 9, tag 18"], answer:3, why:"32-byte lines need 5 offset bits. 64 KB ÷ 32 B = 2,048 lines, ÷ 4 ways = 512 sets, so 9 index bits; tag = 32 − 9 − 5 = 18. Index 11 treats the cache as direct-mapped, one line per set."},
 {id:"p38m4q2", q:"L1 hits in 3 cycles and misses 8% of the time; L2 hits in 15 cycles and 25% of L2 lookups miss; DRAM costs 180 cycles. What is the AMAT?", options:["7.8 cycles","17.4 cycles","49.2 cycles","4.2 cycles"], answer:0, why:"AMAT = 3 + 0.08 × (15 + 0.25 × 180) = 3 + 0.08 × 60 = 7.8 cycles. The 25% is a local rate that applies only to the 8% reaching L2; applying it to every access gives 49.2, and skipping L2 entirely gives 17.4."},
 {id:"p38m4q3", q:"A direct-mapped 4 KB cache has 64-byte lines. A loop alternates reads of a[i] and b[i] (4-byte ints); a starts at 0x00010000 and b at 0x00011000. Almost every access misses. Why, and what fixes it?", options:["Capacity: two arrays overflow the 4 KB cache, so only a larger cache can help","Conflict: a[i] and b[i] map to one index; 2-way or offsetting b fixes it","Compulsory: every line is new each time, so only prefetching helps","False sharing: a and b share lines, so pad each to 64 bytes"], answer:1, why:"Index = bits 11:6. The arrays start 4,096 bytes apart, exactly the cache size, so a[i] and b[i] always land in the same slot and evict each other. Two-way associativity or a one-line offset restores 15 hits per 16 ints. It is not capacity: one line of each would fit."},
 {id:"p38m4q4", q:"Core 0 holds a line in Exclusive. Core 1 then reads the same line, and after that core 0 writes to it. Under MESI, what are the two states afterward?", options:["Core 0 Modified, core 1 Shared with the new value","Core 0 Exclusive, core 1 Shared","Core 0 Modified, core 1 Invalid","Both Modified, each with its own copy"], answer:2, why:"Core 1's read moves both copies to Shared. A write to a Shared line first invalidates every other copy, so core 0 ends Modified (alone, dirty) and core 1 Invalid. MESI invalidates other copies rather than updating them, and two Modified copies would break coherence."},
 {id:"p38m4q5", q:"An L1 DTLB has 64 entries, and a database touches a 64 MiB hot set at random. Compare the TLB's reach with 4 KiB pages and with 2 MiB huge pages.", options:["256 KiB versus 2 MiB; huge pages barely help","64 KiB versus 64 MiB; one entry maps one KiB or MiB","256 KiB versus 128 MiB; huge pages cover the hot set","4 MiB versus 128 MiB; each entry covers 64 pages"], answer:2, why:"Reach = entries × page size: 64 × 4 KiB = 256 KiB, a sliver of 64 MiB, so random access misses the TLB constantly. 64 × 2 MiB = 128 MiB covers the whole hot set. 2 MiB is the size of one huge page, not of all 64 entries."}
],
"p38m5":[
 {id:"p38m5q1", q:"A job is 5% serial and 95% perfectly parallel. Roughly what speedup do 32 cores give?", options:["About 30.4×","About 20.0×","About 32.0×","About 12.5×"], answer:3, why:"Amdahl: 1 / (0.05 + 0.95/32) = 1 / 0.0797 ≈ 12.5×. The 5% serial part takes longer than the whole 95% spread over 32 cores. 20× is the limit with infinite cores (1/0.05), and 30.4× scales only the parallel share."},
 {id:"p38m5q2", q:"An accelerator peaks at 100 TFLOP/s with 2 TB/s of memory bandwidth. A kernel performs 10 FLOPs per byte moved. What can it attain, and what bounds it?", options:["100 TFLOP/s; it is compute-bound","20 TFLOP/s; it is memory-bound","50 TFLOP/s; it sits at the ridge point","5 TFLOP/s; bandwidth divided by intensity"], answer:1, why:"Attainable = min(peak, bandwidth × AI) = min(100, 2 × 10) = 20 TFLOP/s. The ridge is 100 ÷ 2 = 50 FLOP/byte and 10 sits left of it, so the kernel is memory-bound; only moving fewer bytes, not instruction tuning, raises it."},
 {id:"p38m5q3", q:"A 13-billion-parameter model quantized to 4 bits runs on an M4 Pro with 273 GB/s of unified memory bandwidth. Roughly what caps its token generation rate?", options:["About 42 tokens/s, from reading 6.5 GB per token","About 21 tokens/s, from reading 13 GB per token","About 10 tokens/s, from reading 26 GB per token","Its TFLOPS, since generation is compute-bound"], answer:0, why:"Each token reads every weight once: 13 × 10⁹ × 0.5 bytes = 6.5 GB, and 273 ÷ 6.5 ≈ 42 tokens/s. 13 GB assumes 8-bit weights and 26 GB 16-bit. At an intensity near 4 FLOP/byte, generation is memory-bound, so TFLOPS do not set the limit."},
 {id:"p38m5q4", q:"A library ships one RVV 1.0 loop that calls vsetvli each iteration. The same binary runs on a core with VLEN = 128 and one with VLEN = 1024. What happens?", options:["It must be rebuilt for each VLEN, as AVX2 code is for AVX-512","It runs only on the 128-bit core it was compiled and tuned for","It runs on both, with more elements per pass on the wider core","It runs on both, but the wider core still does 128 bits per pass"], answer:2, why:"RVV code is vector-length agnostic: vsetvli returns how many elements this hardware handles per iteration, so the 1024-bit core does eight times as many per pass with no recompilation. Rebuilding per width is the packed-SIMD model of SSE, AVX2 and AVX-512 that RVV avoids."},
 {id:"p38m5q5", q:"Dynamic power scales as C × V² × f. Raising a core's clock by 20% requires 10% more voltage. Roughly how much does dynamic power rise?", options:["About 21%","About 30%","About 45%","About 32%"], answer:2, why:"1.2 × 1.1² = 1.2 × 1.21 ≈ 1.45, about 45% more power for 20% more clock. Adding the percentages (30%) or forgetting to square the voltage (32%) understates it; this superlinear cost is why clocks stalled once Dennard scaling ended."}
],
"p38m6":[
 {id:"p38m6q1", q:"An iCEBreaker has a 12 MHz clock. Using the lesson's blink pattern, you want the LED to toggle every 0.5 s. Which compare value and smallest counter width work?", options:["11,999,999 with a 24-bit counter","5,999,999 with a 22-bit counter","6,000,000 with a 23-bit counter","5,999,999 with a 23-bit counter"], answer:3, why:"Half a second at 12 MHz is 6,000,000 cycles, counted 0 to 5,999,999. 2²² = 4,194,304 is too small and 2²³ = 8,388,608 fits, so 23 bits. 11,999,999 toggles once a second, and comparing with 6,000,000 makes each half-period one cycle too long."},
 {id:"p38m6q2", q:"Intending a swap, a designer writes:\nalways @(posedge clk) begin a = b; b = a; end\nWhat hardware does this describe?", options:["A swap of a and b on every rising edge","Both registers holding b's old value after each edge","Both registers holding a's old value after each edge","A latch, because no else branch assigns them"], answer:1, why:"Blocking assignments update in order: a takes b, then b takes the new a, which is b again, so the swap becomes a copy. With non-blocking a <= b; b <= a; both right-hand sides are sampled first and the registers truly swap, as real flip-flops do."},
 {id:"p38m6q3", q:"A path has t_cq 0.4 ns, logic 4.6 ns and setup 0.2 ns. You split the logic into two equal halves with a pipeline register. What are fmax before and after?", options:["About 217 MHz, then about 435 MHz","About 192 MHz, then about 345 MHz","About 192 MHz, then about 385 MHz","About 200 MHz, then about 400 MHz"], answer:1, why:"Before: 1 / (0.4 + 4.6 + 0.2) = 1 / 5.2 ns ≈ 192 MHz. After: 1 / (0.4 + 2.3 + 0.2) = 1 / 2.9 ns ≈ 345 MHz. The flip-flop overhead is paid in every stage, so it is not a clean doubling; 217 and 435 MHz ignore that overhead entirely."},
 {id:"p38m6q4", q:"A UART transmitter runs at 9,600 baud, 8N1, from a 12 MHz clock. What divider does it need, and what is the maximum payload rate?", options:["1,250 cycles per bit; 960 bytes/s","1,250 cycles per bit; 1,200 bytes/s","125 cycles per bit; 9,600 bytes/s","1,250 cycles per bit; 9,600 bytes/s"], answer:0, why:"12,000,000 ÷ 9,600 = 1,250 cycles per bit, with no error. Each byte costs 10 bit-times (start, 8 data, stop), so 9,600 ÷ 10 = 960 bytes per second. 1,200 bytes/s divides by 8 and forgets the start and stop bits."},
 {id:"p38m6q5", q:"A push button wired straight into an FPGA state machine passes timing in nextpnr, yet the machine sometimes jumps to impossible states when the button is pressed. Best diagnosis and fix?", options:["fmax is too low for the design; lower the clock frequency until the glitches stop","A missing default case inferred a latch; add one to every case","Async input causing metastability; synchronize with two flip-flops and debounce","The state register uses <=; switch to = for an immediate update"], answer:2, why:"The button is asynchronous to the clock, so it can violate setup and hold, leave flip-flops metastable and give different state bits different values; static timing never checks external inputs. A two-flip-flop synchronizer plus debouncing fixes it. A slower clock does not make the input synchronous."}
],
"p38m7":[
 {id:"p38m7q1", q:"Project A needs a RISC-V core in the roughly 200 LUTs left on a nearly full iCE40. Project B must boot Linux on an ECP5. Which cores fit?", options:["PicoRV32 for A, SERV for B","SERV for A, PicoRV32 for B","SERV for A, VexRiscv for B","VexRiscv for A, PicoRV32 for B"], answer:2, why:"SERV is a bit-serial RV32I in about 200 LUTs, while PicoRV32 needs 750–2,000. Linux needs an MMU and caches, which VexRiscv can be configured with; PicoRV32 is in-order and multi-cycle without an MMU, so it runs firmware, not Linux."},
 {id:"p38m7q2", q:"Bare-metal code declares #define UART_THR (*(unsigned char *)0x10000000) without volatile. Built with -O2, puts(\"hello\") prints only \"o\" or nothing. Why?", options:["The 16550 needs a delay between bytes, and -O2 removed the loop that provided it","Without volatile, the compiler may merge the repeated stores into one","0x10000000 is where RAM starts on QEMU virt, so the bytes went to memory instead","-O2 emits compressed instructions the UART cannot decode"], answer:1, why:"To the compiler, repeated stores through a plain pointer with no reads in between are redundant, so it may keep only the last or drop them all. volatile forces every access to happen, in order, which a hardware register needs. On QEMU virt, RAM starts at 0x80000000."},
 {id:"p38m7q3", q:"A bare-metal program's global int counter; reads 0 under QEMU but random values on the FPGA board. Which startup step is missing from start.S?", options:["Zeroing the region from _bss_start to _bss_end","Setting sp to _stack_top before calling main","Writing the trap vector address into mtvec","Copying .text from flash into RAM before main"], answer:0, why:"Uninitialized globals live in .bss, which C promises starts at zero, but after reset real RAM holds whatever it powered up with; start.S must clear it before main. QEMU happens to start with zeroed RAM, hiding the bug. A missing sp would crash, not leave stale values."},
 {id:"p38m7q4", q:"PicoRV32 was built with the M option but without C. Firmware compiled with -march=rv32imc -mabi=ilp32 crashes at the first compressed instruction. What fixes it?", options:["Rebuild with -march=rv64gc -mabi=lp64d","Rebuild with -march=rv32imc -mabi=lp64","Keep the flags and enable F in the core","Rebuild with -march=rv32im -mabi=ilp32"], answer:3, why:"-march must match what the core implements. C makes the compiler emit 16-bit compressed encodings, which a core without C treats as illegal instructions. rv32im keeps multiply and divide and produces only 32-bit words; rv64gc targets a 64-bit core with floating point, which PicoRV32 is not."},
 {id:"p38m7q5", q:"Your design synthesizes to about 5,000 standard cells and needs 12 outputs. What is the main obstacle to submitting it as one Tiny Tapeout tile?", options:["Its 12 outputs, since a tile offers exactly 8 pins in total","Its size, about five times the ~1,000 cells a tile holds","Nothing, since tiles hold any design that passes simulation","Its clock, since tiles have no clock or reset input"], answer:1, why:"A tile is about 160 × 100 µm, roughly a thousand standard cells, so 5,000 cells needs a much smaller design. Outputs are less of a problem: besides 8 dedicated outputs there are 8 bidirectional pins, so 12 outputs can fit. Tiles do provide clock and reset."}
]
});
Object.assign(window.LQ,{
"p39m1":[
 {id:"p39m1q1", q:"A $2.99 monthly iOS subscription has 2,000 subscribers in its first year. The developer earns under $1 million a year and is enrolled in Apple's Small Business Program. What is the monthly net after Apple's commission?", options:["$5,083","$4,186","$5,382","$5,980"], answer:0, why:"Gross is 2,000 × $2.99 = $5,980. The Small Business Program cuts Apple's rate to 15%, so the developer keeps 85%: $5,083. $4,186 applies the standard 30%, $5,382 a 10% fee, and $5,980 ignores the commission entirely."},
 {id:"p39m1q2", q:"An iOS app starts a two-minute file upload with an ordinary in-app request when the user taps Upload. Users who then switch to another app report that the upload never finishes. What explains it?", options:["iOS halts all of an app's network traffic as soon as the screen turns off to save power","It is suspended seconds after backgrounding; long work needs a system-run background task","applicationWillTerminate runs on every app switch and cancels the request","The upload needs a purpose string in Info.plist to continue in the background"], answer:1, why:"A backgrounded iOS app gets a few seconds to finish and is then suspended; long-running work exists only through specific background modes or system-scheduled tasks. applicationWillTerminate is not called on an app switch and is never guaranteed to run at all."},
 {id:"p39m1q3", q:"An iOS app terminates the instant it first opens the camera, on every device, before any permission dialog appears. What is the most likely cause?", options:["The user denied camera access in an earlier session","Info.plist lacks an NSCameraUsageDescription string","The privacy manifest lacks a required-reason API entry","App Tracking Transparency was not requested first"], answer:1, why:"Accessing protected data without a purpose string in Info.plist terminates the app on the spot, before any prompt. A denial makes the access fail gracefully rather than crash. The privacy manifest and App Tracking Transparency govern other things: required-reason APIs and the advertising identifier."},
 {id:"p39m1q4", q:"A startup's product is an AR measuring app built on a custom camera pipeline that needs every frame and each new OS camera API on launch day, and it should live for many years. Which approach fits the lesson's four questions?", options:["A PWA, so updates ship instantly without store review","Flutter, because its own renderer guarantees identical frames","Native: Kotlin with Compose and Swift with SwiftUI","React Native with Expo, so a web team can ship it quickly"], answer:2, why:"Heavy camera and graphics work, day-one OS APIs and a long lifetime all favor native, which amortizes two codebases over years. Flutter and React Native reach new camera APIs only through plugins or native modules, and a PWA has the weakest device access of all."},
 {id:"p39m1q5", q:"A learner with only a Windows PC wants to build a native SwiftUI app and run it on their own iPhone. Which route is lawful?", options:["Install macOS in a virtual machine on the PC and run Xcode","Use the Windows Swift toolchain, which includes SwiftUI and the Simulator","Run Xcode under WSL2, since macOS and Linux are both Unix","Rent a cloud Mac by the hour and run Xcode on it remotely"], answer:3, why:"Xcode runs only on macOS, and the macOS license forbids running it on non-Apple hardware, so a VM on a PC is not a lawful path. The Swift toolchain for Windows and Linux teaches the language but has no SwiftUI, UIKit or Simulator. A rented cloud Mac is legitimate."}
],
"p39m2":[
 {id:"p39m2q1", q:"You add data object Empty : NotesUiState to the sealed interface. NotesScreen's when (val s = state) has branches for Loading, Error and Ready and no else. What happens?", options:["It compiles, and Empty silently renders nothing","The build fails until the when handles Empty","It compiles, but throws at runtime when Empty arrives","It compiles with a warning, and Empty falls into Loading"], answer:1, why:"A when over a sealed type must be exhaustive, so adding a subtype turns every when without a branch for it into a compile error. That is the point of sealed UI states: the compiler lists each screen you forgot. With no else branch there is no silent fall-through."},
 {id:"p39m2q2", q:"On a search screen, the query the user typed must survive rotation and process death, and the 2,000 results come from Room. Where should each live?", options:["Query in SavedStateHandle; results observed from Room via the ViewModel","Both in remember { mutableStateOf() } inside the composable","Both in SavedStateHandle, so nothing needs reloading after death","Both in plain ViewModel fields, since the ViewModel outlives the process"], answer:0, why:"SavedStateHandle restores small values like a query after process death, while the results belong in Room, the source of truth, re-streamed on relaunch. remember survives neither rotation nor death, a ViewModel survives only configuration changes, and saved state is for small values, not result sets."},
 {id:"p39m2q3", q:"A LazyColumn shows 5,000 messages with no key parameter, and a new message is inserted at the top. Compared with keying rows by id, what happens?", options:["Nothing differs, since Compose always matches list items by comparing their full contents","Unkeyed, all 5,000 rows recompose, because LazyColumn composes every item it holds","Keyed rows recompose too, because the list object itself changed","Unkeyed, rows match by position, so each visible row gets new data and recomposes"], answer:3, why:"Without keys a lazy list ties each slot to its index, so inserting at position 0 shifts data into every visible slot and they all recompose. With key = { it.id } Compose sees the existing rows unchanged and composes only the new one. A LazyColumn composes only visible rows plus a buffer."},
 {id:"p39m2q4", q:"A @Dao contains @Query(\"SELECT * FROM notes WHERE titel = :t\"), misspelling the title column. When does the developer find out?", options:["At run time, when a user's device first executes that query","Only if a unit test happens to call that DAO method","At build time, as Room's processor checks the SQL","When the database migration runs on first launch"], answer:2, why:"Room's annotation processor (KSP) validates @Query SQL against the entity schema at compile time, so a misspelled column is a build error rather than a crash in the field. That check is one of the main reasons to use Room instead of raw SQL strings."},
 {id:"p39m2q5", q:"You want a fast JVM unit test of NotesViewModel that needs no device and no database. What does the lesson's structure let you do?", options:["Hand a fake NotesRepository to its constructor and use runTest","Start an emulator and point the ViewModel at a real Room database","Turn the repository into a global singleton that the test overwrites first","Use createComposeRule() to drive the ViewModel through the screen"], answer:0, why:"Because the ViewModel receives its repository through an @Inject constructor, a test can pass a fake directly and drive it with runTest in milliseconds. A global singleton is the hand-wired pattern Hilt replaces, and createComposeRule tests the screen, not the ViewModel alone."}
],
"p39m3":[
 {id:"p39m3q1", q:"A developer makes the app's shared WeatherModel a struct and hands it to two views. One view calls load(), but the other never shows the forecast. Why?", options:["Structs are copied on assignment, so each view owns a separate model","The load ran off the main thread, so SwiftUI never refreshed the UI","SwiftUI caches the first value of every struct and ignores changes","Optionals inside structs cannot be updated after initialization"], answer:0, why:"Structs have value semantics: passing one makes an independent copy, so the load filled one copy while the other view still holds nil. Shared, mutable state that several views observe belongs in a class marked @Observable, which gives every view the same instance."},
 {id:"p39m3q2", q:"Pick property wrappers for: a toggle that only one view uses; a child slider that edits its parent's value; a cart shared by five screens.", options:["@Binding, @State, and an @Observable class","@Observable for all three, injected by @Environment","@State, @Binding, and an @Observable class","@State for all three, copied into each view"], answer:2, why:"@State is private view-local state, @Binding gives a child read-write access to state its parent owns, and an @Observable class holds model state shared across views. Making everything @State copies values so screens drift apart; making everything observable adds shared objects where a local value would do."},
 {id:"p39m3q3", q:"A view uses .task(id: city) { await model.load(city: city) } and the user quickly types A-u-s-t-i-n into the city field. What happens to the loads?", options:["Six loads run in parallel, and whichever finishes last wins","Each change cancels the load in flight and starts another","Only the first load runs, since .task fires once per view","The loads queue up and run one after another in order"], answer:1, why:"With an id, .task cancels its running task and starts a new one whenever the id changes, so structured concurrency cleans up stale loads for you. Uncancelled parallel loads could finish out of order and show the forecast for \"Aus\" after \"Austin\"."},
 {id:"p39m3q4", q:"An iOS app fetches JSON from http://api.example.com. The request fails on every device, although the server is up and answers in a desktop browser. What is the most likely cause?", options:["URLSession needs a purpose string before any network request","JSONDecoder rejects responses that lack an ETag header","Devices block every domain not listed in the privacy manifest","App Transport Security blocks plain HTTP without an exception"], answer:3, why:"App Transport Security requires HTTPS with TLS 1.2 or later and blocks plain HTTP unless the app declares an exception, which review will question; the fix is HTTPS on the server. Network access needs no purpose string, and the privacy manifest covers required-reason APIs, not domains."},
 {id:"p39m3q5", q:"A private repo's iOS CI job takes 20 minutes per build and runs 150 times a month. At the lesson's per-minute rates, ignoring included minutes, what do macOS runners cost, compared with Linux?", options:["About $18 a month, against $186 on Linux","About $186 a month, against $18 on Linux","About $1,860 a month, against $180 on Linux","About $93 a month, against $9 on Linux"], answer:1, why:"20 × 150 = 3,000 minutes. At $0.062 a minute macOS costs 3,000 × 0.062 = $186; Linux at $0.006 would be $18, about ten times less. That ratio is why teams run Android and unit tests on Linux and keep macOS runners for the iOS build."}
],
"p39m4":[
 {id:"p39m4q1", q:"An Android-first company has years of Kotlin business rules and a strong Android team. It wants an iOS app that keeps native UI without rewriting those rules. Which option fits?", options:["Flutter, rewriting all of the logic and UI once in Dart","React Native with Expo and a TypeScript rewrite","Kotlin Multiplatform, shared one module at a time","A PWA wrapping the Android app's web views"], answer:2, why:"KMP compiles shared Kotlin into a framework iOS can call, so existing rules move over one module at a time while the UI stays native in SwiftUI. Flutter and React Native both mean rewriting the logic in another language, the expensive part this team wants to keep."},
 {id:"p39m4q2", q:"In the Flutter notes screen, someone changes _add to call notes.insert(0, t) and controller.clear() without wrapping them in setState. What does the user see?", options:["The note appears at once, because the list is a final field the widget already reads","The field clears, but the note shows only after some other rebuild","Flutter throws an error because state changed outside setState","The note appears twice, since build runs once for each change"], answer:1, why:"setState is Flutter's explicit \"state changed, rebuild me\". Mutating the list without it changes the data but schedules no build, so the ListView keeps the old items until another rebuild happens. The field still clears because the TextField listens to its controller directly."},
 {id:"p39m4q3", q:"An Expo app must read traces from a Bluetooth LE OTDR, and the Expo SDK has no module for that device. What does the lesson say this takes?", options:["Nothing extra: JavaScript can call the BLE radio directly through Hermes","An over-the-air update that enables the Bluetooth permission","Rewriting the whole app in Flutter, which ships BLE built in","A config plugin and a native module written in Kotlin and Swift"], answer:3, why:"Cross-platform code still reaches native code at the hardware edge: Expo needs a config plugin plus a native module in Kotlin and Swift for an unsupported device API. JavaScript cannot touch the radio directly, and Flutter would need a plugin or platform channel too."},
 {id:"p39m4q4", q:"A team has a Next.js web app and is starting a mobile app. They want one copy of the validation rules and the API client. Which setup matches the lesson's strongest sharing story?", options:["Expo plus the web app, both importing a shared TypeScript package","A Flutter app compiled to the web with CanvasKit, replacing the Next.js site","Two native apps that call the web app's server-rendered pages","A Kotlin Multiplatform module compiled to Kotlin/JS for the website"], answer:0, why:"React Native with Expo shares the most with a web app: a monorepo package of TypeScript models, validation and API clients imported by both, in a language the team already knows. Flutter web suits dashboards more than text-heavy sites, and KMP would add a new language to a TypeScript team."},
 {id:"p39m4q5", q:"A Flutter team is setting up CI for both platforms. Which plan matches the lesson's pattern?", options:["Linux runners only, since one Dart codebase needs one test platform","Widget tests on Linux only; integration tests add nothing for cross-platform","Linux for Android and unit tests, macOS for iOS, plus a device farm","Windows runners hosting both the Android emulator and the iOS Simulator"], answer:2, why:"iOS builds and Simulator runs need macOS, Android and host unit tests run cheaply on Linux, and a device farm covers real hardware. One codebase does not mean one test platform: channels, permissions, keyboards and fonts differ, and those gaps are where cross-platform bugs live."}
],
"p39m5":[
 {id:"p39m5q1", q:"A photo grid uses 120 dp square cells on a 3× density screen. If each image is decoded at cell size as ARGB_8888, roughly how much memory do 40 visible thumbnails need?", options:["About 2.3 MB","About 21 MB","About 5.2 MB","About 1.9 GB"], answer:1, why:"Each cell is 120 × 3 = 360 px square, so a thumbnail costs 360 × 360 × 4 ≈ 0.52 MB, and 40 cost about 21 MB. 2.3 MB forgets the density multiplier, 5.2 MB forgets the 4 bytes per pixel, and 1.9 GB is 40 full 12-megapixel decodes."},
 {id:"p39m5q2", q:"A newest-first feed loads pages with LIMIT 20 OFFSET n. While the user reads page 2, five new posts arrive at the top. What does page 3 (OFFSET 40) show, and what fixes it?", options:["Five posts are skipped; a larger page size fixes it","Exactly the right posts, since OFFSET counts from the first query","The five new posts; sorting oldest-first fixes it","Five repeats from page 2; keyset paging fixes it"], answer:3, why:"The five new rows push everything down five places, so OFFSET 40 now starts at what was row 36, repeating the end of page 2. Keyset paging asks for rows after the last one seen, which stays stable as items arrive and uses the index instead of walking skipped rows."},
 {id:"p39m5q3", q:"A response carries Cache-Control: max-age=300 and ETag \"v7\". The app requests it again after 2 minutes and again after 10 minutes; the resource has not changed. What happens each time?", options:["Both times a full 200 download, because ETags only matter for uploads","2 min: from cache, no request; 10 min: If-None-Match gets a 304","2 min: revalidated with a 304; 10 min: a full 200 download","Both times from cache with no request at all, since the ETag still matches"], answer:1, why:"Within max-age (300 s) the cached copy is fresh and is used without touching the network. Once it is stale, the client revalidates with If-None-Match: \"v7\", and an unchanged resource returns 304 Not Modified, a few hundred bytes instead of the full body."},
 {id:"p39m5q4", q:"On a 120 Hz phone, Perfetto shows list frames taking 11 ms because each row formats a date and parses EXIF during composition. What are the diagnosis and the fix?", options:["Fine, because 11 ms is comfortably inside the 16.7 ms frame budget","Jank past 8.3 ms; move the work into the repository mapping","Jank, and only shipping a Baseline Profile can bring it back down","Fine at 120 Hz; frames only drop when they exceed 33 ms"], answer:1, why:"At 120 Hz each frame must be ready in 8.3 ms, so 11 ms misses and the old frame repeats. Date formatting and EXIF parsing do not belong in composition; doing them once while mapping data in the repository removes them from every frame. 16.7 ms is the 60 Hz budget."},
 {id:"p39m5q5", q:"Your app builds \"You have 3 new photos\" in code with if (n == 1) \"photo\" else \"photos\". It must ship in Polish and Arabic. What is the right approach?", options:["Keep the code and translate the words photo and photos for each language","Always show the plural form, which every language accepts","Quantity strings in resources, with each locale's own plural forms","Test with the en-XA pseudolocale, which corrects plural forms"], answer:2, why:"Plural rules differ: English needs one and other, Polish one, few and many, Arabic all six CLDR categories. Quantity strings, or String Catalog plural variants, let each translation supply its own forms. A pseudolocale exposes layout and hard-coded-string problems; it does not fix grammar."}
],
"p39m6":[
 {id:"p39m6q1", q:"A BLE sensor log is 30 KB (30,720 bytes). How many notifications does it take at the default 23-byte ATT MTU, and after negotiating a 247-byte MTU?", options:["1,336 versus 125","1,536 versus 126","3,072 versus 252","1,536 versus 128"], answer:1, why:"Each packet loses 3 bytes to the ATT header, so 23 carries 20 bytes of payload and 247 carries 244. 30,720 ÷ 20 = 1,536, and 30,720 ÷ 244 = 125.9, so 126 notifications. Dividing by the full MTU (1,336 and 125) ignores the header."},
 {id:"p39m6q2", q:"A delivery app must confirm arrival at a site five times in a ten-hour shift. Which design fits least privilege and least power?", options:["Background location with continuous high-accuracy tracking all shift","Low-power priority (about 10 km) running continuously to save battery","Foreground location, one high-accuracy fix per check-in, then stop","Passive priority alone, waiting for other apps to request fixes"], answer:2, why:"A check-in needs a precise position only at that moment, so foreground access and one fix keep GPS on for seconds, not hours. Continuous background tracking needs a separate grant and Play review. Low-power priority is accurate only to about 10 km, too coarse to confirm a site."},
 {id:"p39m6q3", q:"An Android app must upload a log once a night whenever the phone has network, even after a reboot, and the exact time may drift by hours. What should run it?", options:["A foreground service that stays alive all night","A silent push from the server that triggers each upload","A thread started in Application.onCreate that loops forever","WorkManager periodic work with a network constraint"], answer:3, why:"WorkManager runs deferrable, guaranteed work under constraints and survives reboots, which is exactly this job. A foreground service needs a visible notification and is time-limited for data sync, silent pushes are throttled and must never carry correctness, and a looping thread dies with the process."},
 {id:"p39m6q4", q:"Your app pins only the current server key's SPKI hash, with no backup pin and no expiration. Next month operations rotates the TLS key before an app update ships. What happens?", options:["Nothing, because pinning only checks the CA's name","Only rooted devices fail; normal phones fall back","Every installed copy stops connecting to the server","The OS quietly falls back to standard CA validation"], answer:2, why:"A pin accepts only the listed public key, so once the server presents a new one every installed copy fails the TLS check and stays broken until users update. That is why the lesson calls for a backup pin and an expiration date, so stale apps fail open rather than fail dead."},
 {id:"p39m6q5", q:"A developer ships a third-party API secret in the APK, AES-encrypted with a key that is also in the app's code. How should a reviewer assess it?", options:["Safe, since AES-256 cannot be broken in practice","Unsafe: both can be decompiled; keep the secret server-side","Safe once R8 has obfuscated every class and field name in the app","Safe if the result is stored in SharedPreferences"], answer:1, why:"Any key compiled into an APK or IPA can be extracted by decompiling it, so encrypting with it only adds a step. Secrets belong on a server that issues short-lived tokens. R8 renames symbols but leaves constant bytes intact, and AES strength is irrelevant once the key is in hand."}
],
"p39m7":[
 {id:"p39m7q1", q:"Baseline user-perceived crash rate is 0.3%. A new build adds a crash hitting 1.2% of users who have it. Where does the overall rate land at a 20% staged rollout and at 100%, against Play's 1.09% bad-behavior line?", options:["0.54% at 20% and 1.5% at 100%; over the line only at full rollout","1.5% at both stages, since the crash rate applies per user on the build","0.24% at 20% and 1.2% at 100%; over only at full rollout","0.54% at 20% and 1.5% at 100%; under the line both times"], answer:0, why:"The new crash reaches only the share on the build: 0.3 + 0.2 × 1.2 = 0.54% at 20%, under the line, and 0.3 + 1.2 = 1.5% at 100%, over it. Leaving out the 0.3% baseline gives 0.24% and 1.2%. That gap is why each rollout step is gated."},
 {id:"p39m7q2", q:"A serious bug appears during a 10% staged rollout, and you halt it. What happens to the users who already updated, and what would have protected them?", options:["Play rolls them back to the previous version automatically within a day","Play removes the build from their phones at the next device check-in","The halt switches off the new build's changed code paths for them","They keep it; only a prepared remote-config flag or a fixed build helps"], answer:3, why:"Halting stops new installs only; everyone who already has the build keeps it. Protection must be prepared beforehand: risky features behind remote-config flags you can switch off without a release, then a fixed build. No store rolls back an installed version."},
 {id:"p39m7q3", q:"App Review rejects your app under guideline 2.1 because the reviewer could not get past the login screen. What is the most effective response?", options:["Resubmit unchanged, hoping a different reviewer approves it","Remove the login screen entirely so that no reviewer ever reaches it","Reply in Resolution Center with demo credentials and a recording","Submit it again as a new app under a different name"], answer:2, why:"A 2.1 completeness rejection is usually fixed in a day: give the reviewer working demo credentials, state the fix, and add a short screen recording if the flow is hard to find. Resubmitting unchanged repeats the failure, and a renamed duplicate invites a 4.3 spam rejection."},
 {id:"p39m7q4", q:"Google's analysis found that every 6 MB added to an APK cut install conversion by about 1%. Your app grows from 18 MB to 42 MB. Roughly what install loss does that predict?", options:["About 1%","About 4%","About 7%","About 24%"], answer:1, why:"The growth is 42 − 18 = 24 MB, and 24 ÷ 6 = 4 steps of about 1% each, so roughly 4% fewer installs. 7% divides the whole 42 MB by 6, and 24% treats each megabyte as a percent; the lesson's answer is a size budget that CI enforces."},
 {id:"p39m7q5", q:"A laptop holding your Apple Distribution certificate's private key is stolen, and you revoke the certificate. What happens to your app that is already on the App Store?", options:["It is removed until you resubmit under a new bundle ID","It keeps working; issue a new certificate for later builds","It stops launching on users' phones within 24 hours","It can never be updated again, like a lost Android signing key"], answer:1, why:"Apple anchors identity, so revoking a distribution certificate does not affect apps already on the App Store; you create a new certificate and profile and keep shipping updates. The never-update trap applies to an Android app whose self-managed signing key is lost."}
]
});
Object.assign(window.LQ,{
"p40m1":[
 {id:"p40m1q1", q:"A fixed-step loop uses DT = 1/60 s. The accumulator holds 5.0 ms when a 40.0 ms frame arrives. How many simulation steps run, and what is alpha?", options:["2 steps; alpha ≈ 0.70","3 steps; alpha ≈ 0.70","2 steps; alpha ≈ 0.30","3 steps; alpha ≈ 0.00"], answer:0, why:"acc = 5.0 + 40.0 = 45.0 ms. Two 16.67 ms steps fit (33.3 ms), leaving 11.7 ms, so alpha = 11.7 ÷ 16.67 ≈ 0.70 and the frame is drawn 70% of the way from the previous state to the current one. A third step would need 50 ms."},
 {id:"p40m1q2", q:"At a 60 fps target, the main thread spends 5 ms on scripts, 3.5 ms on physics, 2 ms on animation, 1.5 ms on AI and 6 ms on render submission; the GPU needs 12 ms per frame in parallel. What frame rate results, and what bounds it?", options:["About 33 fps, since CPU and GPU times add to 30 ms","About 83 fps, bounded by the GPU's 12 ms","A steady 60 fps, since vsync holds the rate","About 55 fps, CPU-bound at 18 ms"], answer:3, why:"CPU work sums to 5 + 3.5 + 2 + 1.5 + 6 = 18 ms. CPU and GPU work as a pipeline on different frames, so frame time is roughly the slower of the two: 18 ms, about 55 fps. Adding them double-counts overlapping work, and GPU optimizations will not help here."},
 {id:"p40m1q3", q:"A ball moves at 400 px/s toward a 10 px thick paddle, using a variable timestep and a point-like collision test. Above what frame time can one update carry the ball straight through the paddle?", options:["About 25 ms","About 100 ms","About 2.5 ms","Never, since multiplying by dt removes the risk"], answer:0, why:"Tunneling begins when one step moves the ball farther than the paddle is thick: 400 px/s × dt > 10 px, so dt > 25 ms. One hitch longer than that can put the ball above the paddle in one update and below it in the next. Scaling by dt fixes speed, not missed collisions."},
 {id:"p40m1q4", q:"A Unity script calls rb.AddForce(thrust) inside Update(). On a 240 Hz monitor the car accelerates much faster than on a 60 Hz one. What explains it, and what is the fix?", options:["Rigidbody interpolation is off; enable it and keep Update","Time.deltaTime is wrong at 240 Hz; switch to Time.time","The physics step shrinks on a 240 Hz display; raise fixedDeltaTime","Force is added per rendered frame; move it to FixedUpdate"], answer:3, why:"Update runs once per rendered frame, so at 240 Hz four times as many AddForce calls land in each 0.02 s physics step as at 60 Hz. Physics forces belong in FixedUpdate, which runs at Time.fixedDeltaTime regardless of the display. The physics step does not change with the monitor."},
 {id:"p40m1q5", q:"A two-person studio's Unreal Engine game grosses US$3 million. Under the terms in the lesson, what royalty does Epic collect?", options:["$150,000","$0","$100,000","$50,000"], answer:2, why:"Unreal charges 5% only on gross above US$1 million per product: 5% × (3,000,000 − 1,000,000) = US$100,000. Charging 5% on the whole US$3 million gives US$150,000. Godot, by contrast, charges nothing at any revenue."}
],
"p40m2":[
 {id:"p40m2q1", q:"A surface with albedo 0.8 is lit by a white light of intensity 1 arriving 60° from the surface normal. What diffuse brightness does Lambert's law give?", options:["0.40","0.69","0.80","0.20"], answer:0, why:"Brightness = albedo × light × max(0, N·L) = 0.8 × 1 × cos 60° = 0.8 × 0.5 = 0.40. 0.69 uses sin 60° instead of the cosine of the angle from the normal, and 0.80 ignores the angle entirely."},
 {id:"p40m2q2", q:"A camera has a 90° vertical field of view and renders to 1200 × 800 (aspect 1.5). A view-space point is 3 m right, 2 m up and 10 m in front. Where does it land in pixels, with the origin at the top left?", options:["(780, 320)","(720, 480)","(660, 320)","(720, 320)"], answer:3, why:"f = 1 ÷ tan 45° = 1, so x_ndc = 3 ÷ (1.5 × 10) = 0.2 and y_ndc = 2 ÷ 10 = 0.2. Pixels: x = 1.2 ÷ 2 × 1200 = 720 and y = 0.8 ÷ 2 × 800 = 320. 780 forgets the aspect ratio; 480 forgets that screen y runs downward."},
 {id:"p40m2q3", q:"A 4096 × 4096 albedo texture gets a full mip chain. What does it occupy in video memory as uncompressed RGBA8, and as BC1?", options:["64 MiB versus 8 MiB","85.3 MiB versus 21.3 MiB","16 MiB versus 2 MiB","85.3 MiB versus 10.7 MiB"], answer:3, why:"4096² texels × 4 bytes = 64 MiB, and mipmaps add one third: 85.3 MiB. BC1 stores half a byte per texel and stays compressed in video memory: 8 MiB, 10.7 MiB with mips. 21.3 MiB is BC7's 1 byte per texel, and 64 and 8 MiB leave out the mip chain."},
 {id:"p40m2q4", q:"A shader computes correct linear lighting, giving a face a linear red of 0.16, but writes the value to the sRGB display without encoding it. What does the player see?", options:["Too dark: linear values are displayed as if already sRGB","Washed out: the display doubles every value it receives","No change, because monitors convert linear values automatically","Only highlights are wrong, since diffuse color is unaffected"], answer:0, why:"Displays expect sRGB-encoded values. Encoding linear 0.16 gives about 0.437 (111 in 8 bits); writing 0.16 directly shows 41, visibly too dark. Light in linear space and encode once at output; washed-out results come from the opposite mistake, such as encoding twice."},
 {id:"p40m2q5", q:"A fragment shader branches on a per-pixel noise value, so about half the pixels in every 32-thread warp take each side. One side costs 40 instructions, the other 60. Roughly what does each warp pay?", options:["About 50 instructions, the average of the two sides","About 60 instructions, only the longer side","About 100 instructions, both sides in turn","About 40 instructions, only the shorter side"], answer:2, why:"Threads in a warp execute in lockstep, so when they diverge the warp runs both paths one after the other with inactive lanes masked off: about 40 + 60 = 100. If every pixel in a warp went the same way, it would pay only that side's cost."}
],
"p40m3":[
 {id:"p40m3q1", q:"Three turrets each fire 25 bullets per second, and each bullet lives 4 seconds. Following the lesson's sizing rule with 25% headroom, how large should the bullet pool be?", options:["300","375","100","125"], answer:1, why:"Peak live bullets = fire rate × lifetime × shooters = 25 × 4 × 3 = 300; adding 25% headroom gives 375. 100 counts a single turret, and 125 is that figure with headroom. A pool that runs dry falls back to Instantiate and brings the garbage back."},
 {id:"p40m3q2", q:"Update() sets scoreText.text = \"Score: \" + score every frame, and each bullet is created with Instantiate and removed with Destroy. The Profiler shows a GC spike every few seconds. Which pair of fixes removes it?", options:["Pool the bullets and update the text only when the score changes","Call GC.Collect() every frame so each collection stays small","Move both pieces of code into FixedUpdate so they run less often","Rewrite the HUD in ECS so its strings bypass the collector"], answer:0, why:"Both lines allocate in steady state: a new string every frame and new bullet objects every shot. Pooling reuses bullets, and updating the text only on change, with a non-allocating SetText, removes the per-frame string, so GC Alloc reads 0 B. Forcing a collection every frame makes every frame pay."},
 {id:"p40m3q3", q:"A game writes its save by overwriting save.json in place. A power cut mid-write leaves a truncated file, and players lose everything. What is the robust fix?", options:["Store the whole save in PlayerPrefs, which the engine never leaves corrupted","Save more often, so less progress is lost each time","Switch to BinaryFormatter, which writes faster and smaller","Write a temp file, then rename it over the old one; keep a backup"], answer:3, why:"An atomic rename swaps in the new file only after it is completely written, so a crash leaves either the old save or the new one, never half of each; a rolling backup covers the rest. PlayerPrefs is a settings store, and BinaryFormatter is dangerous on untrusted data and removed from modern .NET."},
 {id:"p40m3q4", q:"The Soldier prefab has speed 4 and health 100. FastSoldier is a prefab variant that overrides speed to 7. A designer then changes Soldier to speed 5 and health 120. What does FastSoldier have now?", options:["Speed 7, health 120","Speed 7, health 100","Speed 5, health 120","Speed 5, health 100"], answer:0, why:"A variant inherits every change to its base except the properties it overrides. FastSoldier's override keeps speed at 7, while its untouched health follows the base to 120. Predicting that mix of inherited and overridden values is exactly what the Associate exam asks."},
 {id:"p40m3q5", q:"A Unity script calls GetComponent<Rigidbody2D>() every frame and checks the jump action's WasPressedThisFrame() inside FixedUpdate. Players report jumps that sometimes do not register. What fixes both problems?", options:["Move all of it into LateUpdate, which runs after the physics step","Keep input in FixedUpdate but lower fixedDeltaTime so it runs every frame","Call GetComponent in Start and leave the input check in FixedUpdate","Cache it in Awake; read the press in Update, jump in FixedUpdate"], answer:3, why:"FixedUpdate can run zero times in a rendered frame, so a press that is true for only one frame can fall between physics steps; read it in Update and apply it in the next FixedUpdate. Calling GetComponent every frame wastes time; cache the reference once in Awake."}
],
"p40m4":[
 {id:"p40m4q1", q:"A designer wants a 2 m jump that peaks in 0.25 s. Using the lesson's formulas, what gravity and launch speed does the controller need?", options:["g = 32 m/s², v₀ = 8 m/s","g = 9.81 m/s², v₀ = 6.3 m/s","g = 64 m/s², v₀ = 8 m/s","g = 64 m/s², v₀ = 16 m/s"], answer:3, why:"g = 2h ÷ t² = 2 × 2 ÷ 0.0625 = 64 m/s², and v₀ = 2h ÷ t = 4 ÷ 0.25 = 16 m/s. Real gravity with a 6.3 m/s launch also reaches 2 m but takes about 0.64 s to peak, which feels floaty; dropping the factor of 2 gives 32 and 8."},
 {id:"p40m4q2", q:"A scene has 2,000 dynamic bodies. How many pairs does a brute-force narrow phase test each step, and what does a uniform grid sized to typical objects change?", options:["About 2 million; a grid leaves each body only a few neighbors","4 million pairs; the grid halves that by skipping duplicate pairs","About 2 million pairs; the grid helps only once bodies stop moving","2,000 pairs; the grid makes no difference at this size"], answer:0, why:"n(n − 1) ÷ 2 = 2,000 × 1,999 ÷ 2 = 1,999,000 pairs. A grid lets each body test only its own and neighboring cells, so the broad phase becomes roughly linear. 4 million counts every pair twice, and letting bodies sleep is a separate optimization."},
 {id:"p40m4q3", q:"A ball falls from rest for 0.5 s with a 60 Hz step and g = 9.81 m/s²; the exact distance is 1.226 m. What do explicit Euler and semi-implicit Euler report?", options:["Explicit 1.185 m, semi-implicit 1.267 m","Explicit 1.267 m, semi-implicit 1.185 m","Both exactly 1.226 m at this small step","Explicit 1.185 m, semi-implicit 1.226 m"], answer:0, why:"Over n = 30 steps, explicit Euler moves with the old velocity: g·dt²·n(n−1)/2 = 1.185 m, short. Semi-implicit Euler uses the new velocity: g·dt²·n(n+1)/2 = 1.267 m, long. Both are first-order and neither is exact; correctly initialized Verlet is exact for constant acceleration."},
 {id:"p40m4q4", q:"A replay system records only player inputs. Replays play back perfectly on the developer's x86 PC but drift apart on the ARM build of the same game. What are the likely cause and fix?", options:["A memory leak on ARM corrupts the state; profile it and free the buffers","ARM's byte order corrupts the replay file; store it as text instead","Float results differ across CPUs; use strict determinism or fixed-point","Input lag differs on ARM; add a fixed input delay"], answer:2, why:"Input-only replays need bit-identical simulation. Compilers reorder and fuse float operations, and SIMD widths and math libraries differ, so tiny differences compound until the replay diverges. Engineered determinism (Jolt or Box2D v3 strict settings) or fixed-point math fixes it."},
 {id:"p40m4q5", q:"A dungeon generator takes a seed, yet two players who enter the same seed get different maps. Which bug is the most likely cause?", options:["It draws from a global RNG that other code also uses","The seed is too short to define a whole dungeon","Cellular automata cannot produce the same map twice","The flood-fill step picks a random cave to keep"], answer:0, why:"A seed reproduces a world only if generation uses its own seeded generator and draws numbers in the same order. A shared global generator is also advanced by other systems, such as menus or particles, so the sequence differs each session. Cellular automata and flood fill are deterministic given their inputs."}
],
"p40m5":[
 {id:"p40m5q1", q:"A blend tree places idle at 0, walk at 1.5 and run at 5 m/s. The guard moves at 2.2 m/s. What does it play?", options:["80% walk, 20% run","20% walk, 80% run","44% run, 56% walk","100% walk until 5 m/s"], answer:0, why:"2.2 m/s lies between walk (1.5) and run (5): (2.2 − 1.5) ÷ (5 − 1.5) = 0.2 of the way, so 20% run and 80% walk. A blend tree mixes the two neighboring clips by position along the parameter, not by dividing speed by the top speed."},
 {id:"p40m5q2", q:"A rhythm game uses a 1,024-sample audio buffer at 48 kHz. How much latency does the buffer add, and what does cutting it to 256 samples give?", options:["10.7 ms, then 2.7 ms","2.1 ms, then 0.5 ms","21.3 ms, then 10.7 ms","21.3 ms, then 5.3 ms"], answer:3, why:"Buffer latency = samples ÷ sample rate: 1,024 ÷ 48,000 = 21.3 ms, and 256 ÷ 48,000 = 5.3 ms, before the output device adds its own delay. 10.7 ms is the lesson's 512-sample figure. Smaller buffers cut latency but risk dropouts if the mixer misses a deadline."},
 {id:"p40m5q3", q:"A guard's tree is Selector[ Sequence(CanSeePlayer, InRange 2 m, Attack), Sequence(CanSeePlayer, MoveTo player), Sequence(HasLastKnownPosition, MoveTo it, Search 4 s), Patrol ]. The player is visible 6 m away. What runs this tick?", options:["Attack, since the player is visible","Patrol, since the first branch failed","MoveTo player, from the second branch","Search at the last known position"], answer:2, why:"The Selector tries children in order. The first Sequence fails at InRange 2 m, so the Selector moves on; in the second, CanSeePlayer succeeds and MoveTo returns Running. A Selector stops at the first child that does not fail, so later branches such as Patrol never run."},
 {id:"p40m5q4", q:"A camera uses x += (target − x) · (1 − e^(−k·dt)) with k = 8 per second. What per-frame factor does it apply at 60 fps and at 120 fps?", options:["0.125 at 60 fps, 0.064 at 120 fps","0.133 at 60 fps, 0.067 at 120 fps","0.125 at both frame rates","0.8 at 60 fps, 0.4 at 120 fps"], answer:0, why:"1 − e^(−8/60) ≈ 0.125 and 1 − e^(−8/120) ≈ 0.064. The smaller factor, applied twice as often, converges exactly as fast per second. 0.133 and 0.067 are k·dt, a linear approximation, and one fixed factor at every rate would converge faster on faster machines."},
 {id:"p40m5q5", q:"A game marks weak points in red and safe zones in green, and explosions flash the screen five times a second. Which set of changes follows the guidelines in the lesson?", options:["Swap red for orange so more players can see it, and keep the flashes for danger","Add a colorblind filter but keep color as the only cue","Remove the explosions' sound so the flashes stand out more","Add icons beside the colors; keep flashes under 3 per second, with a toggle"], answer:3, why:"Never let color carry meaning alone: add shapes or icons that survive color-vision deficiency. Stay under three flashes per second and let players turn flashing and shake off. Another hue, or a filter that still relies on color alone, leaves the core problem in place."}
],
"p40m6":[
 {id:"p40m6q1", q:"A shooter's round trip is 120 ms, and their client interpolates 100 ms behind. How far back must the server rewind hitboxes for their shot, and what happens with a 200 ms rewind cap?", options:["220 ms; over the cap, so they must lead their targets","120 ms; inside the cap, so the shot is judged as seen","60 ms, the one-way delay; inside the cap","100 ms, the interpolation delay alone; inside the cap"], answer:0, why:"The server rewinds by round trip plus interpolation delay: 120 + 100 = 220 ms. That exceeds the 200 ms cap, so the server cannot rewind far enough and the player must aim ahead. Counting only the round trip or the one-way delay forgets that the target was drawn 100 ms in the past."},
 {id:"p40m6q2", q:"A match has 24 players. Each snapshot carries 24 entities × 20 bytes plus 40 bytes of headers and is sent at 20 Hz. Roughly what does each client receive, and what does the server send upstream in total?", options:["520 B/s per client; about 12.5 KB/s upstream","10.4 KB/s per client; 10.4 KB/s upstream","83 KB/s per client; about 2 MB/s upstream","10.4 KB/s each; about 250 KB/s upstream"], answer:3, why:"One snapshot is 24 × 20 + 40 = 520 bytes; at 20 Hz that is 10,400 B/s, about 10.4 KB/s (83 kbps) per client. The server sends that to all 24 clients: about 250 KB/s, or 2 Mbps. 83 KB/s confuses kilobits with kilobytes, and 520 B/s forgets the send rate."},
 {id:"p40m6q3", q:"A two-player online fighting game runs a deterministic simulation and must feel instant at a 60 ms round trip. Which architecture fits?", options:["Rollback, re-simulating when late inputs arrive","Lockstep, waiting for both players' inputs before every frame","Client–server with the opponent interpolated 100 ms behind","TCP lockstep, so no input is ever lost or reordered"], answer:0, why:"Rollback (GGPO-style) applies your input immediately, predicts the opponent's, and re-simulates from the last confirmed frame when the real input arrives, using the determinism the game already has. Lockstep's input delay equals the slowest link, and interpolation would show the opponent in the past."},
 {id:"p40m6q4", q:"A server accepts each client's reported position every tick, and players start teleporting across the map. What is the design fix?", options:["Encrypt the position packets so cheaters cannot read them","Ship kernel anti-cheat, which makes server checks unnecessary","Send inputs; the server moves players and caps speed per tick","Switch to TCP so position packets arrive reliably"], answer:2, why:"Accepting positions makes the client authoritative, and the attacker owns the client. Sending inputs and letting the server simulate, with checks such as maximum speed per tick, keeps the truth on the server. Encryption and anti-cheat software support detection but never replace server authority."},
 {id:"p40m6q5", q:"A development build on target hardware shows main thread 8 ms, render thread 6 ms and GPU 21 ms, and halving the resolution makes the frame rate jump. Which work should come first?", options:["Pool objects to remove the garbage-collection spikes from scripts","Tick AI at 10 Hz and simplify the physics layers","Merge scripts so Update runs fewer times per frame","Cut pixel cost: overdraw, shaders, shadows, or an upscaler"], answer:3, why:"The GPU at 21 ms is the slowest stage, and the jump at lower resolution shows it is pixel-bound, so reduce per-pixel work or render fewer pixels with DLSS, FSR or XeSS. The CPU threads already fit the budget, so pooling, AI ticking and script changes would not raise the frame rate."}
],
"p40m7":[
 {id:"p40m7q1", q:"A US$14.99 Steam game sells 3,000 copies in year one. Assume 10% refunds and 10% of the remainder in sales taxes and VAT, then Valve's 30%. Roughly what does the developer keep?", options:["About $31,500","About $36,400","About $25,500","About $28,300"], answer:2, why:"Gross is 3,000 × 14.99 = $44,970; after refunds and taxes the adjusted gross is 44,970 × 0.9 × 0.9 ≈ $36,426, and Valve's 30% leaves about $25,498. Taking 30% straight off gross ($31,479) ignores refunds and taxes, and $36,400 forgets Valve's share."},
 {id:"p40m7q2", q:"A design review finds that a children's game sells loot boxes for gems, shows prices only in gems, runs an \"offer ends in 5:00\" timer that resets every session, and hides the odds. Which changes bring it in line?", options:["Keep the design, because gems are a virtual currency rather than real money","Add the ESRB In-Game Purchases label and leave everything else as it is","Raise the age rating, then keep the design unchanged","Real-currency prices, no fake timer, odds shown, spending limits"], answer:3, why:"The lesson's standard is prices in real currency, no fake urgency aimed at children, disclosed odds and spending limits; the FTC's US$245 million refund order against Epic targeted exactly such interface tricks. Gems hide real spending, and a label or rating does not fix the design."},
 {id:"p40m7q3", q:"In a playtest, three of five testers fail at the same gap and suggest adding a double jump. What should the designer conclude?", options:["Add the double jump, because a majority of the testers asked for it","The gap is a real problem; find out why before picking a fix","Ignore it, since five testers are too few to matter","Test only with expert players, who will clear the gap"], answer:1, why:"Players find problems reliably and propose fixes poorly: three of five failing in one place is strong evidence the gap is wrong, perhaps its distance, readability or the coyote-time window, but the double jump is only a suggestion. Five fresh testers is the usual rule of thumb for surfacing most issues."},
 {id:"p40m7q4", q:"A developer switches a Unity PC game to the IL2CPP backend to stop cheaters from altering its logic. How should that be assessed?", options:["Faster, but not protection; keep what matters server-side","It makes the compiled game practically impossible to reverse-engineer","It is required on Windows, so it changes nothing","It replaces any need for server validation or an anti-cheat service"], answer:0, why:"IL2CPP compiles C# ahead of time to C++, which is faster and required on iOS, and its output is harder to read, but reverse-engineering tools still open it. Anything that matters, such as currency, loot and match results, must be validated on the server, because the attacker owns the client."},
 {id:"p40m7q5", q:"A Godot 4 web export with threads enabled fails on a host with an error that SharedArrayBuffer is unavailable. What is the simplest fix the lesson describes?", options:["Switch the project to the Forward+ renderer, which browsers support better","Compile the web build with IL2CPP instead","Use a single-threaded export, which needs no isolation headers","Ship a Windows build, since browsers cannot run Godot"], answer:2, why:"Threaded web builds need SharedArrayBuffer, which browsers enable only when the host sends cross-origin isolation headers. A single-threaded export avoids that requirement. Godot's web export uses the Compatibility renderer, not Forward+, and IL2CPP is a Unity backend."}
]
});
